import { memo } from "react";
import { Icon, Text } from "@kit/index.js";
import { Translate, useNumberFormat } from "travel-platform";
import styles from "./Autocomplete.module.css";

const TrendingItem = memo(function TrendingItem({ destination }) {
    const format = useNumberFormat();
    return (
        <li className={styles.item}>
            <span className={styles.button}>
                <Icon name="city" size="large" className={styles.icon} />
                <span className={styles.text}>
                    <span className={styles.title}>{destination.name}</span>
                    <span className={styles.subtitle}><Translate id="sb.properties" params={{ count: format(destination.count) }} /></span>
                </span>
            </span>
        </li>
    );
});

// Shown when the field has focus and no text, rendered with the page.
export function TrendingDestinations({ destinations, visible }) {
    return (
        <div className={visible ? styles.list : styles.hidden} aria-hidden={!visible}>
            <Text variant="strong_2" className={styles.heading}><Translate id="sb.trending" /></Text>
            <ul className={styles.trending}>{destinations.map((destination) => <TrendingItem key={destination.id} destination={destination} />)}</ul>
        </div>
    );
}
