import { useCallback, useEffect, useRef, useState } from "react";
import { Button, Checkbox } from "@kit/index.js";
import { TrackingScope, Translate, useSearchState, useTrack, useTranslation } from "travel-platform";
import "./catalog.js";
import { DestinationField } from "./DestinationField.jsx";
import { DatesField } from "./DatesField.jsx";
import { OccupancyField } from "./OccupancyField.jsx";
import styles from "./SearchBox.module.css";

function draftFrom(state, destinationName) {
    return {
        destination: { destId: state.destId, destType: state.destType, label: destinationName },
        checkin: state.checkin,
        checkout: state.checkout,
        adults: state.adults,
        children: state.children,
        rooms: state.rooms,
    };
}

function useDraft(destinationName) {
    const { state } = useSearchState();
    const [draft, setDraft] = useState(() => draftFrom(state, destinationName));
    // The destination's name arrives with the results, after the search
    // state has changed, so the draft follows both.
    const synced = useRef({ state, destinationName });
    useEffect(() => {
        if (synced.current.state === state && synced.current.destinationName === destinationName)
            return;
        synced.current = { state, destinationName };
        setDraft(draftFrom(state, destinationName));
    }, [state, destinationName]);
    const update = useCallback((patch) => setDraft((d) => ({ ...d, ...patch })), []);
    return [draft, update];
}

export default function SearchBox({ destinationName, trending = [] }) {
    const t = useTranslation();
    const track = useTrack();
    const { navigate } = useSearchState();
    const [draft, update] = useDraft(destinationName);
    const [open, setOpen] = useState(null);
    const [work, setWork] = useState(false);
    const close = useCallback(() => setOpen(null), []);

    const submit = useCallback((event) => {
        event.preventDefault();
        if (!draft.destination.destId || !draft.checkout)
            return;
        track("searchbox.submit", { destType: draft.destination.destType, nights: draft.checkout > draft.checkin });
        navigate((state) => ({
            ...state,
            destId: draft.destination.destId,
            destType: draft.destination.destType,
            checkin: draft.checkin,
            checkout: draft.checkout,
            adults: draft.adults,
            children: draft.children,
            rooms: draft.rooms,
            page: 0,
            filters: draft.destination.destId === state.destId ? state.filters : [],
        }), "searchbox");
    }, [draft, navigate, track]);

    return (
        <TrackingScope surface="searchbox">
            <form className={styles.searchbox} onSubmit={submit} data-testid="searchbox" role="search">
                <div className={styles.fields}>
                    <DestinationField destination={draft.destination} trending={trending} onChange={(destination) => update({ destination })} />
                    <DatesField checkin={draft.checkin} checkout={draft.checkout} open={open === "dates"} onOpen={() => setOpen(open === "dates" ? null : "dates")} onClose={close} onChange={update} />
                    <OccupancyField adults={draft.adults} children={draft.children} rooms={draft.rooms} open={open === "occupancy"} onOpen={() => setOpen(open === "occupancy" ? null : "occupancy")} onClose={close} onChange={update} />
                    <Button type="submit" size="large" className={styles.submit} data-testid="searchbox-submit"><Translate id="sb.search" /></Button>
                </div>
                <Checkbox label={t("sb.work")} checked={work} onChange={(e) => setWork(e.target.checked)} className={styles.work} />
            </form>
        </TrackingScope>
    );
}
