import { useEffect } from "react";
import { gql, useQuery } from "@apollo/client";
import { Icon } from "@kit/index.js";
import { emitStepEvent, useLocalized, useTranslation } from "travel-platform";
import { DESTINATION_AUTOCOMPLETE } from "../../graphql/search.mjs";
import { autocompleteVariables } from "../../shared/search-input.mjs";
import styles from "./Autocomplete.module.css";

const QUERY = gql(DESTINATION_AUTOCOMPLETE);

function Highlighted({ text, ranges }) {
    if (!ranges?.length)
        return text;
    const { start, end } = ranges[0];
    return (
        <>
            {text.slice(0, start)}
            <mark className={styles.mark}>{text.slice(start, end)}</mark>
            {text.slice(end)}
        </>
    );
}

function AutocompleteItem({ suggestion, position, label, onSelect }) {
    const t = useTranslation();
    return (
        <li role="option" aria-selected="false" className={styles.item} id={`ac-${suggestion.id}`}>
            <button type="button" className={styles.button} aria-label={label} onClick={() => onSelect(suggestion, position)} data-testid="autocomplete-result" data-dest-id={suggestion.destination.destId}>
                <Icon name={suggestion.icon.name} size="large" className={styles.icon} />
                <span className={styles.text}>
                    <span className={styles.title}><Highlighted text={suggestion.title} ranges={suggestion.highlights} /></span>
                    <span className={styles.subtitle}>{suggestion.subtitle}</span>
                </span>
                {suggestion.propertyCount > 1 ? <span className={styles.count}>{t("sb.properties", { count: suggestion.propertyCount })}</span> : null}
            </button>
        </li>
    );
}

export function AutocompleteList({ query, onSelect }) {
    const t = useTranslation();
    const localized = useLocalized();
    const { data, loading } = useQuery(QUERY, { variables: autocompleteVariables(query) });
    const results = data?.autocomplete.results;
    useEffect(() => {
        if (!loading && results)
            emitStepEvent("autocomplete-settled", { query, count: results.length });
    }, [loading, results, query]);
    if (!results)
        return null;
    return (
        <ul id="destination-suggestions" role="listbox" aria-label={t("sb.suggestions")} className={styles.list} data-testid="autocomplete-results">
            {results.map((suggestion, i) => <AutocompleteItem key={suggestion.id} suggestion={suggestion} position={i} onSelect={onSelect} label={localized(suggestion.label)} />)}
        </ul>
    );
}
