import { useRef } from "react";
import loadable from "@loadable/component";
import { Icon, Popover } from "@kit/index.js";
import { registerLazy, useDateFormat, useTranslation } from "travel-platform";
import styles from "./SearchBox.module.css";

const DatePicker = registerLazy(loadable(() => import("./DatePicker.jsx")));

export function DatesField({ checkin, checkout, open, onOpen, onClose, onChange }) {
    const t = useTranslation();
    const format = useDateFormat({ weekday: "short", day: "numeric", month: "short" });
    const anchorRef = useRef(null);
    return (
        <div className={styles.field}>
            <button ref={anchorRef} type="button" className={styles.trigger} aria-label={t("sb.dates")} aria-expanded={open} onClick={onOpen} data-testid="date-display-field">
                <Icon name="calendar" size="medium" />
                <span className={styles.triggerText} suppressHydrationWarning>{checkin && checkout ? `${format(checkin)} — ${format(checkout)}` : t("sb.dates_placeholder")}</span>
            </button>
            <Popover open={open} anchorRef={anchorRef} onClose={onClose} title={t("sb.dates_title")} closeLabel={t("sb.close")} testId="datepicker">
                <DatePicker checkin={checkin} checkout={checkout} onChange={onChange} onDone={onClose} />
            </Popover>
        </div>
    );
}
